import type { Shape } from "./gen";
export interface RangeShot {
  x: number;
  y: number;
  pts: number;
  hit: boolean;
  cm: number;
}
export interface RangeCamera {
  height: number;
  zoom: number;
}
export function targetPoint(x: number, y: number, camera: RangeCamera) {
  const k = Math.min(0.76, camera.height * 0.00135) * (1 + camera.zoom * 0.42);
  return {
    x: 300 + (x - 300) * k,
    y: camera.height * (0.38 + camera.zoom * 0.04) + (y - 210) * k,
  };
}
export function rangePoint(x: number, y: number, height: number) {
  return {
    x: 300 + (x - 300) / Math.min(0.76, height * 0.00135),
    y: 210 + (y - height * 0.38) / Math.min(0.76, height * 0.00135),
  };
}
interface Scene {
  height: number;
  time: number;
  wind: number;
  aim: { x: number; y: number };
  power: number;
  draw: number;
  zoom: number;
  review: boolean;
  reduced: boolean;
  flight: { u: number; x: number; y: number } | null;
}
function line(
  c: CanvasRenderingContext2D,
  points: number[],
  color: string,
  width = 1,
) {
  c.strokeStyle = color;
  c.lineWidth = width;
  c.beginPath();
  c.moveTo(points[0], points[1]);
  for (let i = 2; i < points.length; i += 2) c.lineTo(points[i], points[i + 1]);
  c.stroke();
}
function tree(
  c: CanvasRenderingContext2D,
  x: number,
  y: number,
  size: number,
  color: string,
) {
  c.fillStyle = color;
  c.beginPath();
  c.moveTo(x, y - size);
  c.lineTo(x - size * 0.34, y - size * 0.3);
  c.lineTo(x - size * 0.15, y - size * 0.3);
  c.lineTo(x - size * 0.48, y);
  c.lineTo(x + size * 0.48, y);
  c.lineTo(x + size * 0.15, y - size * 0.3);
  c.lineTo(x + size * 0.34, y - size * 0.3);
  c.closePath();
  c.fill();
  c.fillRect(x - size * 0.035, y, size * 0.07, size * 0.2);
}
/** A fixed first-person camera; only the impact inspection moves toward the target. */
export function drawRange(
  c: CanvasRenderingContext2D,
  shape: Shape,
  shots: RangeShot[],
  s: Scene,
) {
  const h = s.height,
    horizon = h * 0.55;
  c.fillStyle = "#dce8e6";
  c.fillRect(0, 0, 600, h);
  c.fillStyle = "#f2eee0";
  c.beginPath();
  c.arc(465, 74, 28, 0, Math.PI * 2);
  c.fill();
  c.fillStyle = "#b7c9be";
  c.beginPath();
  c.moveTo(0, horizon);
  c.bezierCurveTo(90, horizon - 95, 135, horizon - 75, 240, horizon - 25);
  c.bezierCurveTo(390, horizon - 120, 475, horizon - 90, 600, horizon - 40);
  c.lineTo(600, horizon + 30);
  c.lineTo(0, horizon + 30);
  c.fill();
  for (let i = 0; i < 19; i++)
    tree(c, i * 37 - 22, horizon + 10, 38 + ((i * 23) % 48), "#8da898");
  c.fillStyle = "#9eae87";
  c.fillRect(0, horizon + 12, 600, h);
  c.fillStyle = "#acb995";
  c.beginPath();
  c.moveTo(276, horizon + 12);
  c.lineTo(324, horizon + 12);
  c.lineTo(560, h);
  c.lineTo(40, h);
  c.closePath();
  c.fill();
  // Converging ground marks place the archer on a lane rather than above a diagram.
  for (let i = 0; i < 4; i++) {
    const y = horizon + (h - horizon) * Math.pow((i + 1) / 5, 1.9),
      half = 20 + (y - horizon) * 0.47;
    line(c, [300 - half, y, 300 + half, y], "#8c9d78", 1);
  }
  c.fillStyle = "#809572";
  c.beginPath();
  c.ellipse(300, horizon + 40, 139, 14, 0, 0, Math.PI * 2);
  c.fill();
  const camera = { height: h, zoom: s.zoom },
    center = targetPoint(300, 210, camera),
    k = Math.min(0.76, h * 0.00135) * (1 + s.zoom * 0.42);
  c.save();
  c.translate(center.x, center.y);
  c.scale(k, k);
  line(c, [-118, 147, -153, 257], "#705843", 12);
  line(c, [118, 147, 153, 257], "#705843", 12);
  line(c, [-125, 205, 125, 205], "#705843", 7);
  c.fillStyle = "#8b6a4c";
  c.fillRect(-202, -202, 404, 404);
  c.fillStyle = "#e9dfc8";
  c.fillRect(-194, -194, 388, 388);
  c.strokeStyle = "#d7c9ad";
  c.lineWidth = 1;
  for (let i = -180; i < 190; i += 17) {
    c.beginPath();
    c.moveTo(-190, i);
    c.lineTo(190, i);
    c.stroke();
  }
  c.strokeStyle = "#b6a789";
  c.lineWidth = 1;
  c.strokeRect(-186, -186, 372, 372);
  c.fillStyle = "#7d6951";
  for (const x of [-186, 186])
    for (const y of [-186, 186]) {
      c.beginPath();
      c.arc(x, y, 3, 0, Math.PI * 2);
      c.fill();
    }
  c.save();
  c.shadowColor = "#57432e35";
  c.shadowBlur = 7;
  c.shadowOffsetY = 5;
  c.drawImage(shape.sp, -190, -190, 380, 380);
  c.restore();
  if (s.review) {
    const cx = (shape.c[0] - 0.5) * 380,
      cy = (shape.c[1] - 0.5) * 380;
    c.strokeStyle = "#faf7ed";
    c.lineWidth = 6;
    c.beginPath();
    c.arc(cx, cy, 16, 0, Math.PI * 2);
    c.stroke();
    c.strokeStyle = "#2f6456";
    c.lineWidth = 2;
    c.stroke();
    c.fillStyle = "#2f6456";
    c.beginPath();
    c.arc(cx, cy, 3, 0, Math.PI * 2);
    c.fill();
  }
  for (let i = 0; i < shots.length; i++) {
    const shot = shots[i],
      x = shot.x - 300,
      y = shot.y - 210;
    if (x < -195 || x > 195 || y < -195 || y > 195) continue;
    line(c, [x, y, x + 7, y - 18], "#f9f4e8", 5);
    line(c, [x, y, x + 7, y - 18], "#313c36", 2);
    c.fillStyle = shot.hit ? "#b74f35" : "#59635d";
    c.beginPath();
    c.arc(x + 7, y - 18, 5, 0, Math.PI * 2);
    c.fill();
  }
  c.restore();
  // Windsock at target depth. Its direction is the same wind used by the shot.
  const flagX = 83,
    flagY = horizon - 108;
  line(c, [flagX, flagY, flagX, horizon + 29], "#687e72", 3);
  const direction = s.wind < 0 ? -1 : 1,
    length = 16 + Math.abs(s.wind) * 10;
  c.fillStyle = "#b6593f";
  c.beginPath();
  c.moveTo(flagX, flagY);
  c.lineTo(
    flagX + direction * length,
    flagY + 6 + (s.reduced ? 0 : Math.sin(s.time * 0.004) * 3),
  );
  c.lineTo(flagX + direction * length, flagY + 16);
  c.lineTo(flagX, flagY + 13);
  c.fill();
  c.fillStyle = "#465949";
  c.font = '600 11px "Bricolage Grotesque", sans-serif';
  c.textAlign = "center";
  c.fillText("12 m", 300, horizon + 87);
  if (!s.review && !s.flight) {
    const p = targetPoint(s.aim.x, s.aim.y, { height: h, zoom: 0 });
    c.strokeStyle = "#ffffff";
    c.lineWidth = 3;
    c.beginPath();
    c.arc(p.x, p.y, 12, 0, Math.PI * 2);
    c.stroke();
    c.strokeStyle = "#243f36";
    c.lineWidth = 1.5;
    c.stroke();
    line(c, [p.x - 21, p.y, p.x - 7, p.y], "#243f36", 1.5);
    line(c, [p.x + 7, p.y, p.x + 21, p.y], "#243f36", 1.5);
    line(c, [p.x, p.y - 21, p.x, p.y - 7], "#243f36", 1.5);
    line(c, [p.x, p.y + 7, p.x, p.y + 21], "#243f36", 1.5);
  }
  if (s.flight) {
    const p = targetPoint(s.flight.x, s.flight.y, camera),
      u = s.flight.u,
      depth = 1 - Math.pow(1 - u, 2);
    const x = 330 + (p.x - 330) * depth,
      y = h + 35 + (p.y - h - 35) * depth,
      size = 52 * (1 - u) + 4;
    c.save();
    c.translate(x, y);
    c.rotate(-0.2 * (1 - u));
    line(c, [0, 0, 0, size * 2], "#f8f1dc", Math.max(1.8, 5 * (1 - u)));
    c.fillStyle = "#b14d32";
    c.beginPath();
    c.moveTo(0, size);
    c.lineTo(-size * 0.22, size * 1.65);
    c.lineTo(0, size * 1.5);
    c.lineTo(size * 0.22, size * 1.65);
    c.closePath();
    c.fill();
    c.restore();
  }
  if (!s.review) {
    c.save();
    const kick = s.flight ? Math.min(1, s.flight.u * 5) : 0;
    c.translate(385, h - 95 + kick * 170);
    c.rotate(0.12 + (s.aim.x - 300) * 0.00035);
    // Near recurve limbs, grip and string surround the forward-facing pin.
    c.lineCap = "round";
    c.strokeStyle = "#503d2e";
    c.lineWidth = 18;
    c.beginPath();
    c.moveTo(62, -230);
    c.bezierCurveTo(100, -195, 16, -85, 0, 0);
    c.bezierCurveTo(-16, 80, 35, 135, -13, 205);
    c.stroke();
    c.strokeStyle = "#b38b55";
    c.lineWidth = 10;
    c.stroke();
    c.strokeStyle = "#d9b87d";
    c.lineWidth = 3;
    c.stroke();
    const pull = s.draw * 40;
    line(c, [62, -230, -54 - pull, 25, -13, 205], "#f5ebd5", 2);
    c.fillStyle = "#35483f";
    c.beginPath();
    c.roundRect(-19, -25, 37, 67, 10);
    c.fill();
    // Forearm and wrapped fingers sit on the near side of the grip.
    c.fillStyle = "#bd9475";
    c.beginPath();
    c.moveTo(-29, 28);
    c.bezierCurveTo(-68, 49, -85, 118, -117, 210);
    c.lineTo(-23, 215);
    c.lineTo(16, 58);
    c.quadraticCurveTo(23, 28, -29, 28);
    c.fill();
    c.fillStyle = "#425c4b";
    c.beginPath();
    c.moveTo(-72, 115);
    c.lineTo(-7, 137);
    c.lineTo(-23, 225);
    c.lineTo(-117, 225);
    c.closePath();
    c.fill();
    c.fillStyle = "#aa7e5e";
    c.beginPath();
    c.roundRect(-27, -6, 39, 59, 13);
    c.fill();
    for (let i = 0; i < 3; i++)
      line(c, [-22, 9 + i * 11, 8, 12 + i * 11], "#8e654a", 2);
    if (!s.flight) {
      line(c, [-58 - pull, 25, -100, -120], "#f5e7c3", 5);
      line(c, [-58 - pull, 25, -100, -120], "#705d43", 1);
      c.fillStyle = "#b64f34";
      c.beginPath();
      c.moveTo(-58 - pull, 25);
      c.lineTo(-82 - pull, 48);
      c.lineTo(-72 - pull, 17);
      c.closePath();
      c.fill();
    }
    c.restore();
  }
}
